package com.friendinneed.expression; import com.friendinneed.emotion.EmotionLabel; import org.springframework.stereotype.Service;
@Service public class ExpressionService { public ExpressionCommand commandForEmotion(EmotionLabel e){return switch(e){case JOY->new ExpressionCommand("HAPPY",.8,null,600);case SADNESS->new ExpressionCommand("SAD",.7,null,600);case SURPRISE->new ExpressionCommand("SURPRISED",.8,null,600);case ANGER->new ExpressionCommand("NEUTRAL",.9,null,600);default->new ExpressionCommand("NEUTRAL",.5,null,400);};} public ExpressionCommand commandForState(String state){return new ExpressionCommand(state,.6,null,300);} }
